import sys

PATH = 'generate_manuscript_nc.py'
src = open(PATH, encoding='utf-8').read().splitlines()

REPL = [
    (r"""p('CKI defines two rates""",
     r"""p('CKI defines two rates: a baseline divergence rate k_n, estimated from housekeeping (HK) gene expression, and a functional divergence rate k_f, estimated from cell-type identity genes; the ratio \u03c9 = k_f/k_n quantifies baseline-normalized functional divergence (Fig. 1). The scope of \u03c9 is bounded by one central assumption, quantified empirically throughout: the HK anchor is valid only where housekeeping expression remains constrained. Functional signal on HK genes is invisible to \u03c9 by construction, and in disease or strong-perturbation contexts the anchor itself shifts (TCGA and IFN-\u03b2 below; Supplementary Note 1), inflating the denominator and deflating the ratio; in such regimes \u03c9 must be read alongside its components, and k_f with a design-matched null is the honest default for ordering claims (Results; Discussion).')"""),
    (r"""p('Here, we show that CKI provides""",
     r"""p('Here, we show that CKI provides a baseline-normalized index of cell-state divergence across five scales. First, random splits of the same mouse cell population (Tabula Muris [8]) yield \u03c9 above 1 (empirical baseline 7.70, 95% CI [7.37, 8.02]). Second, in Tabula Sapiens human data [9], \u03c9 is negatively correlated with all four standard distance metrics\u2014partly a denominator effect (Results). Third, on real technical replicates (30 cross-lane PBMC pairs; 2,161 brain library pairs), \u03c9 shows the lowest drift misreporting among continuous metrics while retaining sensitivity to genuine biology. Fourth, on TCGA data [10,11] (five cancer types, 3,567 samples), CKI uncovers a consistent pan-cancer reversal\u2014tumors less divergent than adjacent non-tumor tissue, attributable to an elevated housekeeping baseline\u2014and resolves lung-adenocarcinoma driver classes: KRAS-mutant tumors retain both functional (k_f) and baseline (k_n) divergence after purity and smoking adjustment, while the apparent EGFR association dissolves. Fifth, in a human brain atlas [12], we quantify a regional differentiation gradient (1.74-fold size-balanced) and screen for anomalously similar cell-type/region pairs; no candidate survives FDR correction, so the screen is a bounded, hypothesis-generating catalogue. Ground-truth simulations complement all five analyses throughout.')"""),
    (r"""p('CKI reframes transcriptomic comparison""",
     r"""p('CKI reframes transcriptomic comparison\u2014from measuring absolute distance to quantifying functional divergence relative to an internal baseline\u2014but is better described as a recombination of established ideas than a conceptual shift: reference genes have long anchored normalization and quality control [29], the constrained-variance property of housekeeping genes is characterized genomically [13,30], and gene-specific noise floors are central to the transcriptional-noise literature [31-33]. CKI combines these ingredients into a per-comparison, design-testable index with explicit split-half calibration and a design-matched permutation null. The key assumption is that HK genes are under stabilizing selection constraining their expression variance; unlike Ka/Ks\u2014where a shared mutation rate cancels mathematically\u2014CKI uses empirically defined HK genes as baseline, lacking comparable mechanistic cancellation, so CKI is a heuristic index rather than a formal measure of selection. The empirical calibration indicates k_f systematically exceeds k_n even for identical populations (Results), so \u03c9_cal = \u03c9 / 7.70 is the operational scale, interpreted against the empirical equivalent-population distribution rather than fixed cut-offs.')"""),
    (r"""p('CKI is a divergence index""",
     r"""p('CKI is a divergence index, not a classifier\u2014by design. Classifying cell types from transcriptomic data is largely solved; CKI answers a complementary question: regardless of labels, how much functional divergence separates two populations relative to their shared baseline? The negative correlation with standard metrics is partly a denominator effect (decomposition, Results), so \u03c9 is a composite of numerator and denominator information rather than an independent dimension. The ratio earns its increment over k_f under controlled ground truth and in drift rejection; on real-data orderings the increment is not established, and k_f with a design-matched null remains the default for ordering claims.')"""),
    (r"""p('The Ka/Ks analogy is heuristically""",
     r"""p('The Ka/Ks analogy is heuristically productive but technically bounded: HK genes are empirically defined rather than mechanistically neutral, and the HK anchor is itself the most strongly constrained expression class, so \u03c9 should be read as functional divergence in excess of a constrained baseline, never as evidence of positive selection. The full correspondence\u2014including its McDonald\u2013Kreitman-style fourth term [34]\u2014and caveats are in Section 1.4.')"""),
    (r"""p('CKI complements rather than replaces""",
     r"""p('CKI complements rather than replaces existing methods: SAMap [35] and SATURN [4] address cross-species alignment and CACIMAR [36] conservation scoring\u2014different questions from within-species functional divergence, so we did not benchmark quantitatively. More broadly, CKI provides a principled null model for any transcriptomic comparison: before concluding two populations differ meaningfully, ask whether the difference exceeds baseline expectation.')"""),
    (r"""p('We also compared CKI with Augur""",
     r"""p('CKI is also not redundant with Augur [37], which prioritizes cell types by condition predictability: rankings are moderately concordant (Augur separability versus class-mean \u03c9 \u03c1 = 0.442; versus k_f \u03c1 = 0.564) with overlapping extremes, at n = 10 classes descriptive only (Supplementary Note 14).')"""),
    (r"""p('The pan-cancer reversal""",
     r"""p('The pan-cancer reversal\u2014tumor specimens less divergent than adjacent non-tumor tissue (mean NN/TT 1.10\u20132.46, cluster-bootstrap CIs excluding 1 in four of five cancers)\u2014is a robust tissue-level observation whose mechanistic reading remains cautious: at bulk resolution the apparent convergence could reflect cell-composition shifts, peritumoral inflammation, or RNA-quality differences rather than genuine transcriptional convergence, and the reversal is predominantly a k_n effect, so the data do not indicate smaller functional divergence of tumor cells. A marker-panel composition check (Supplementary Note 8) attenuates the pooled k_n coefficient by only \u22121.3%\u2014a lower bound, since marker panels are noisy proxies\u2014so the pooled k_n excess is not fully explained by marker-measurable composition (plausibly reflecting tumor-specific housekeeping dysregulation [38]), but composition cannot be excluded either; single-cell or deconvolution-based validation remains necessary. Tumor and adjacent non-tumor aliquots differ systematically in source site and batch, and adjacent non-tumor is not healthy tissue; separating tumor-specific housekeeping elevation from field effects requires an external healthy reference.')"""),
    (r"""p('The cross-organ and cross-brain-region analyses""",
     r"""p('The cross-organ and cross-brain-region analyses show CKI measuring functional differentiation at multiple spatial scales, with one qualification: the brain regional gradient is a composite signal dominated by the k_n denominator (3.21-fold versus 2.03-fold from k_f), not a pure functional-divergence ranking. The candidate screen illustrates a second principle: 31 of 39 Strong candidates showed raw P < 0.05 but none survived correction (minimum q = 0.520; tier-dependence caveats in Supplementary Note 13)\u2014statistical claims at atlas scale require nulls respecting the experimental design, and the absence of FDR-significant signals is itself informative, delimiting what adult transcriptomes alone can support. Preliminary cross-species validation found no significant correlation of per-cell-type mean \u03c9 rankings (Spearman r = \u22120.17, P = 0.55; Supplementary Fig. 11), so cross-species transferability of \u03c9 remains unestablished [39].')"""),
    (r"""p('Although no individual candidate survives FDR correction""",
     r"""p('Although no individual candidate survives FDR correction, several signals are consistent with prior reports\u2014literature anchoring rather than independent validation. Maturation comparisons must use the k_f-only ordering, because the composite is k_n-dominated: under k_f alone the lineage ranks committed OPCs highest (k_f class mean 0.197, highest of ten, with the widest sampling uncertainty) above oligodendrocytes (0.054), with OPCs lowest (0.048)\u2014partially consistent with reports that early oligodendrocyte stages are regionally uniform whereas mature subsets become region-enriched [40,41]\u2014whereas the composite \u03c9 ordering gives the opposite picture; neither supports a monotone-maturation reading. The thalamo-temporal orientation of the mature-oligodendrocyte candidates concentrates on an axis rather than scattering across the 108 regions (two null references in Supplementary Note 13); correspondence with the developmental organization of forebrain oligodendrocytes [25] remains at the level of axis anatomy, pending lineage-tracing or spatial-transcriptomic follow-up.')"""),
    (r"""p('CKI and standard metrics answer different questions""",
     r"""p('CKI and standard metrics answer different questions, and choosing between them reduces to a few practical rules. Use CKI when the question is relative\u2014is the functional divergence between two populations larger than what their own housekeeping baseline varies by, within the same dataset and gene-selection scheme?\u2014offering a normalized scale and a specificity-first screen: a significant \u03c9 rejects label exchangeability under a design-matched null, and functional signal on the anchor is invisible to \u03c9, as the IFN-\u03b2 demonstration makes explicit ([14]; Results). Before trusting fine-grained \u03c9 orderings, diagnose the denominator: if k_n lies in the extreme tail of its own null or correlates with technical covariates, report k_f with the design-matched null directly\u2014in the real data analyzed here, \u03c9 orderings were predominantly denominator-driven (Supplementary Note 9), so k_f plus a design-matched null is the honest default for ordering claims. Use standard metrics when absolute cross-dataset distances are required, for classification, for weak-to-moderate effects at atlas scale, or when the baseline itself is suspect\u2014then interpret k_n and k_f separately rather than trusting \u03c9 alone.')"""),
    (r"""p('For prospective applications we recommend""",
     r"""p('For prospective applications we recommend: (i) at least 100\u2013200 cells per group, below which pseudobulk noise inflates k_n and k_f unpredictably; (ii) the pre-specified HRT Atlas v1.0 housekeeping panel (cki/data/hrt_atlas.csv) rather than data-driven auto-detection; (iii) comparisons only within the same dataset and gene-selection scheme\u2014absolute \u03c9 does not transfer; (iv) calibration within the dataset of interest by split-half sampling, interpreting \u03c9 against that internal baseline rather than the mouse-derived 7.70; (v) a permutation null matching the experimental design (block-shuffle where libraries or donors define blocks; cki.blocknull.block_shuffle_test), expecting bounded sensitivity\u2014\u03c9 rejects neutral drift rather than detecting weak functional shifts.')"""),
    (r"""p('Limitations. Several boundaries""",
     r"""p('Limitations. Several boundaries delimit where \u03c9 can fire and how it should be read. (i) Scope: CKI detects state changes within a given cell type, not cell-type identity; because the housekeeping anchor is cell-type-specific, the k_n baseline is directly comparable only within the same cell type, so limited cross-type discrimination of \u03c9 is expected by design and delineates, rather than limits, its scope; CKI currently operates at the pseudobulk level. (ii) Gene-set definition and calibration: the per-pair k_f scheme selects genes by the observed difference itself, so k_f magnitudes are inflated upper bounds (median 1.61-fold) and absolute tier thresholds are scheme-specific; housekeeping expression may be dysregulated in cancer [38]; and the empirical calibration factor (7.70, 95% CI [7.37, 8.02]) derives from mouse split-half controls, so absolute \u03c9 does not transfer across datasets or gene-selection schemes. Key parameters (top-200 DE genes, 2,000 HVGs, the +1 pseudo-count) are practical defaults, not optimized values. (iii) Data and design: the TCGA analysis is limited to bulk resolution, its per-cancer permutation test holds the identity panel fixed (anti-conservative), and five cancer types make the results exploratory; the brain atlas uses post-mortem tissue, and donor-level PMI and RNA-integrity covariates were unavailable, so regionally differential RNA degradation could masquerade as regional structure in k_n. (iv) Anchor visibility: \u03c9 is structurally insensitive to perturbations that move the housekeeping anchor itself\u2014in simulation, once 500 genes shifted, the ratio collapsed (AUC 0.05\u20130.13)\u2014and donor-paired permutation power vanishes beyond roughly 500 cells per group, bounding the operating window at ~50\u2013200 cells; the scDist results were obtained with a Python approximation of the R package and should be re-verified against the original implementation. (v) Multiple testing and cluster-aware inference: the class-level upper-tail tests and the pair-level lower-tail screen are separate families reported without joint cross-family correction; the block-shuffle null assumes libraries are otherwise exchangeable, so systematic library-level confounding would distort the null in ways the permutation cannot capture (bounded by the pseudo-region negative control; Supplementary Note 12); and B = 1,000 bounds the resolvable P-value at 9.99 \u00d7 10\u207b\u2074, so the per-pair FDR outcome (minimum q = 0.520) is a statement about permutation resolution rather than evidence against any candidate. Full treatments and supporting sensitivity analyses are given in Supplementary Notes 1\u201316.')"""),
    (r"""p('Future directions include""",
     r""""""),
    (r"""p('CKI adapts the baseline-normalization logic""",
     r"""p('CKI adapts the baseline-normalization logic of Ka/Ks to single-cell transcriptomics, decomposing population divergence into a housekeeping baseline rate (k_n) and an identity-gene functional rate (k_f). Across simulation, calibration, cross-organ, pan-cancer, and brain-regional analyses, \u03c9 rankings carried reproducible biological signal while absolute \u03c9 values remain scheme- and dataset-specific; statistical claims at atlas scale require nulls respecting the experimental design; and the absence of FDR-significant candidates is itself an informative bound on what adult transcriptomes alone can support. Released as an open-source Python package with a fully reproducible pipeline, CKI offers an interpretable complement to standard distance metrics, with applications to developmental biology, drug-response profiling, aging research, and evolutionary cell biology.')"""),
]

used = set()
for idx, (pre, new) in enumerate(REPL):
    hits = [i for i, l in enumerate(src) if l.strip().startswith(pre) and i not in used]
    if len(hits) != 1:
        print(f'FAIL[{idx}] matched {len(hits)}: {pre[:70]}')
        sys.exit(1)
    i = hits[0]
    used.add(i)
    ow = len(src[i].split()); nw = len(new.split())
    src[i] = new
    print(f'L{i+1}: {ow} -> {nw}')

open(PATH, 'w', encoding='utf-8').write('\n'.join(src) + '\n')
print('WROTE OK')
